const root=document.querySelector('#manutencao-view');let rows=[];
const e=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const sts=['Solicitado','Em cotação','Aguardando aprovação','Pedido emitido','Aguardando entrega','Recebido / Concluído','Cancelado','Duplicado'];
const opt=(a,v)=>a.map(x=>'<option'+(x===v?' selected':'')+'>'+e(x)+'</option>').join('');
const closed=r=>['Recebido / Concluído','Cancelado','Duplicado'].includes(r.status);
async function load(){const x=await fetch('/api/maintenance');rows=(await x.json()).requests||[];render()}
function render(){root.innerHTML='<div class="maintenance-kpis"><div><strong>'+rows.filter(r=>!closed(r)).length+'</strong><span>Em aberto</span></div><div><strong>'+rows.filter(r=>r.status==='Em cotação').length+'</strong><span>Em cotação</span></div><div><strong>'+rows.filter(r=>r.status==='Aguardando entrega').length+'</strong><span>Aguardando entrega</span></div><div><strong>'+rows.filter(r=>r.priority==='Urgente'&&!closed(r)).length+'</strong><span>Urgentes</span></div></div><section class="panel maintenance-toolbar"><button id="mn">+ Nova solicitação</button><input id="ms" placeholder="Buscar material, serviço, OC, pedido ou responsável"></section><div id="me"></div><section class="panel"><h3>Acompanhamento</h3><div class="table-scroll"><table><thead><tr><th>Nº</th><th>Material / serviço</th><th>Origem</th><th>Solicitante</th><th>Responsável</th><th>Status</th><th>Necessário até</th><th>Pedido</th></tr></thead><tbody id="mb"></tbody></table></div></section>';document.querySelector('#mn').onclick=()=>form({});document.querySelector('#ms').oninput=x=>draw(x.target.value);draw('')}
function draw(q){q=q.toLowerCase();const a=rows.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q)).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));document.querySelector('#mb').innerHTML=a.length?a.map(r=>'<tr data-id="'+r.id+'"><td><strong>'+e(r.number)+'</strong></td><td>'+e(r.description)+'</td><td>'+e(r.origin)+(r.oc?'<small>OC '+e(r.oc)+'</small>':'')+'</td><td>'+e(r.requester)+'</td><td>'+e(r.buyer||'Não assumido')+'</td><td><span class="badge attention">'+e(r.status)+'</span></td><td>'+e(r.neededDate||'—')+'</td><td>'+e(r.systemOrder||'—')+'</td></tr>').join(''):'<tr><td colspan="8">Nenhuma solicitação.</td></tr>';document.querySelectorAll('#mb [data-id]').forEach(x=>x.onclick=()=>form(rows.find(r=>r.id===x.dataset.id)))}
function form(r){document.querySelector('#me').innerHTML='<section class="panel maintenance-editor"><h3>'+(r.id?'Editar '+e(r.number):'Nova solicitação')+'</h3><form id="mf"><div class="maintenance-fields"><label>Tipo<select name="type">'+opt(['Material','Serviço'],r.type||'Material')+'</select></label><label>Origem<select name="origin">'+opt(['OC','WhatsApp','Outro'],r.origin||'WhatsApp')+'</select></label><label>Solicitante<input name="requester" required value="'+e(r.requester||'')+'"></label><label>Responsável pela compra<input name="buyer" value="'+e(r.buyer||'')+'"></label><label>OC<input name="oc" value="'+e(r.oc||'')+'"></label><label>Prioridade<select name="priority">'+opt(['Normal','Alta','Urgente'],r.priority||'Normal')+'</select></label><label>Equipamento / setor<input name="equipment" value="'+e(r.equipment||'')+'"></label><label>Quantidade<input name="quantity" value="'+e(r.quantity||'')+'"></label><label>UM<input name="unit" value="'+e(r.unit||'')+'"></label><label>Necessário até<input type="date" name="neededDate" value="'+e(r.neededDate||'')+'"></label><label>Status<select name="status">'+opt(sts,r.status||'Solicitado')+'</select></label><label>Fornecedor escolhido<input name="supplier" value="'+e(r.supplier||'')+'"></label><label>Pedido no sistema<input name="systemOrder" value="'+e(r.systemOrder||'')+'"></label><label>Entrega prometida<input type="date" name="promisedDate" value="'+e(r.promisedDate||'')+'"></label></div><label>Material / serviço<textarea name="description" required>'+e(r.description||'')+'</textarea></label><div id="mw"></div><label>Observações<textarea name="notes">'+e(r.notes||'')+'</textarea></label><div class="maintenance-actions"><button>Salvar solicitação</button><button type="button" id="mc">Fechar</button></div></form></section>';const f=document.querySelector('#mf'),w=document.querySelector('#mw');const check=()=>{const terms=f.description.value.toLowerCase().split(' ').filter(x=>x.length>3),m=rows.filter(x=>x.id!==r.id&&!closed(x)&&terms.some(t=>x.description.toLowerCase().includes(t))).slice(0,3);w.innerHTML=m.length?'<div class="duplicate-warning"><strong>Possível solicitação duplicada</strong>'+m.map(x=>'<p>'+e(x.number)+' · '+e(x.description)+' · '+e(x.status)+' · '+e(x.buyer||'sem responsável')+'</p>').join('')+'</div>':''};f.description.oninput=check;check();document.querySelector('#mc').onclick=()=>document.querySelector('#me').innerHTML='';f.onsubmit=async x=>{x.preventDefault();const v=Object.fromEntries(new FormData(f));v.id=r.id;v.version=r.version;v.quotesJson=r.quotesJson||'[]';const response=await fetch('/api/maintenance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)}),j=await response.json();if(!response.ok){w.textContent=j.error;return}await load()}}
load();